import torch
from torch import nn
class CausalConv(nn.Module):
    def __init__(self,channels,d):
        super().__init__();self.pad=2*d;self.conv=nn.Conv1d(channels,channels,3,dilation=d)
    def forward(self,x):
        return self.conv(nn.functional.pad(x,(self.pad,0)))
x=torch.randn(3,5,64)
for d in [1,2,4]:
    x=CausalConv(5,d)(x)
print("TCN output:",x.shape)
